 d.wa.unshift({id,memberId,key,name:opts.name||tpl.name,date:TODAY,time:nowT(),status:live?(/^\d{10}$/.test(to)?'Sent':'Failed'):'Sent',text,to,attachment:opts.attachment||'',live:!live,mode:live?'click-to-chat':mode==='linked'?'linked device':'simulated'});
