A.connFlush=c=>{const q=A._conn.splice(0);if(!q.length)return;const s=c.state;Promise.all(q.map(j=>A.cfetch(s,'/send',j).then(()=>null).catch(e=>j.id))).then(bad=>{bad=bad.filter(Boolean);if(bad.length){A.mutate(c,d=>{d.wa=d.wa.map(w=>bad.includes(w.id)?{...w,status:'Failed',error:'Connector not reachable'}:w)});A.toast(c,bad.length+' message(s) failed: the WhatsApp connector is not reachable.','err')}else A.toast(c,q.length+' message'+(q.length>1?'s':'')+' queued on your linked WhatsApp','wa');A.connPoll(c)})};
