A.book=(c,classId,date,memberId)=>{const s=c.state,D=A.D(c);if(!memberId)return A.toast(c,'Choose a member to book.','err');const cl=s.classes.find(x=>x.id===classId);const cur=s.bookings.filter(b=>b.classId===classId&&b.date===date);if(cur.some(b=>b.memberId===memberId&&b.status!=='Cancelled'))return A.toast(c,'Already booked.','err');const full=cur.filter(b=>b.status==='Booked'||b.status==='Attended').length>=cl.cap;
 A.mutate(c,d=>{d.bookings.push({id:'BK-'+(++d.seq.bk),classId,date,memberId,status:full?'Waitlist':'Booked'});if(!full)A._wa(d,s,D,memberId,'class',{},{body:'Hi {{member_name}}, you are booked for '+cl.name+' on '+fd(date)+' at '+F.ftime(cl.time)+'. Please arrive 5 minutes early.\n\n{{gym_name}}'});return {clsPick:''}});A.tickWA(c);A.toast(c,full?'Class full. Added to waitlist.':'Booked and confirmed on WhatsApp')};
