A.cartAdd=(c,sku,delta)=>{const s=c.state;const p=s.products.find(x=>x.id===sku);let cart=[...s.cart];const i=cart.findIndex(x=>x.sku===sku);if(i<0){if(delta>0)cart.push({sku,qty:1})}else{const q=cart[i].qty+delta;if(p.stock!=null&&q>p.stock)return A.toast(c,'Only '+p.stock+' in stock.','err');cart[i]={...cart[i],qty:q};cart=cart.filter(x=>x.qty>0)}if(i<0&&p.stock!=null&&p.stock<1)return;c.setState({cart})};
