A.paSelf=c=>{const S=A.sub(),g=(c.state.settings&&c.state.settings.gym)||{};return {id:'T-101',self:true,gym:g.name||'Power Haus Gym',city:g.city||'Bokaro',owner:'Gym owner (this browser)',phone:g.phone||'',email:g.email||'',started:S.trialStart,plan:S.plan,paidTill:S.paidTill||0,payments:(S.payments||[]).map(p=>({...p,status:p.status||'verified'})),suspended:!!S.suspended,members:(c.state.members||[]).length,notes:S.notes||''}};
