A.paStatus=t=>{const N=Date.now();if(t.suspended)return 'Suspended';if(t.paidTill>N)return 'Active';if(!t.paidTill&&N<t.started+7*864e5)return 'Trial';return t.paidTill?'Expired':'Trial ended'};
A.paEdit=(c,id,fn,msg)=>{if(id==='T-101'){const S=A.sub();const t=A.paSelf(c);fn(t);S.plan=t.plan;S.paidTill=t.paidTill;S.trialStart=t.started;S.suspended=t.suspended;S.notes=t.notes;S.payments=t.payments;A.subSave(c,S)}else{const d=A.paData();const t=d.tenants.find(x=>x.id===id);if(!t)return;fn(t);A.paSave(c,d)}if(msg){A.paLog(msg);A.toast(c,msg)}};
A.paAct=(c,id,act,arg)=>{const D=864e5,N=Date.now();const all=A.paAll(c),t0=all.find(x=>x.id===id);if(!t0)return;const nm=t0.gym;
 if(act==='trial')return A.paEdit(c,id,t=>{t.started=Math.max(t.started,N-7*D)+7*D-(t.started>N-7*D?0:0);if(t.paidTill)return;t.started=N-7*D+ (Math.max(0,t.started+7*D-N))+7*D},'Trial extended by 7 days · '+nm);
 if(act==='grant')return A.paEdit(c,id,t=>{t.paidTill=Math.max(N,t.paidTill||0)+arg*D;if(!t.plan)t.plan='m'},'Granted '+arg+' days · '+nm);
 if(act==='suspend')return A.confirm(c,{title:'Suspend '+nm+'?',body:'Their staff will be locked out until you reactivate. Data is kept.',okLabel:'Suspend',danger:true,onOk:()=>A.paEdit(c,id,t=>{t.suspended=true},'Suspended · '+nm)});
 if(act==='resume')return A.paEdit(c,id,t=>{t.suspended=false},'Reactivated · '+nm);
 if(act==='plan')return A.paEdit(c,id,t=>{t.plan=arg},'Plan set to '+(arg==='y'?'Yearly':'Monthly')+' · '+nm);
 if(act==='verify')return A.paEdit(c,id,t=>{const p=t.payments.find(x=>x.id===arg);if(p)p.status='verified'},'Payment '+arg+' verified · '+nm);
 if(act==='reject')return A.confirm(c,{title:'Reject payment '+arg+'?',body:'The paid days are removed and the account locks if no other time is left.',okLabel:'Reject',danger:true,onOk:()=>A.paEdit(c,id,t=>{const p=t.payments.find(x=>x.id===arg);if(!p||p.status==='rejected')return;p.status='rejected';t.paidTill=Math.max(0,(t.paidTill||0)-(p.plan==='Yearly'?365:30)*D)},'Payment '+arg+' rejected · '+nm)});
 if(act==='lock')return A.confirm(c,{title:'End access for '+nm+'?',body:'Their paid time or trial ends now and the account locks until they pay.',okLabel:'Lock now',danger:true,onOk:()=>A.paEdit(c,id,t=>{t.paidTill=t.paidTill?N-1000:0;t.started=N-8*D},'Access ended · '+nm)});
};
