A.supSend=(c,id,from)=>{const S=from==='admin'?c.state.pa:c.state.sup;const txt=((from==='admin'?S.reply:S.draft)||'').trim();if(!txt)return;const d=A.supData();const t=d.tickets.find(x=>x.id===id);if(!t)return;t.msgs.push({from,text:txt,at:Date.now(),by:c.state.auth&&c.state.auth.name});if(from==='admin'){t.unreadGym=(t.unreadGym||0)+1;t.unreadAdmin=0}else{t.unreadAdmin=(t.unreadAdmin||0)+1;t.unreadGym=0;if(t.status==='Closed')t.status='Open'}A.supSave(c,d);if(from==='admin'){c.setState({pa:{...c.state.pa,reply:''}});A.paLog('Replied to '+t.id+' · '+t.gym)}else A.supSet(c,{draft:''})};
A.supRead=(c,id,side)=>{const d=A.supData();const t=d.tickets.find(x=>x.id===id);if(!t)return;const k=side==='admin'?'unreadAdmin':'unreadGym';if(t[k]){t[k]=0;localStorage.setItem(A.SUPKEY,JSON.stringify(d))}};
